(()=>{"use strict";const esc=t=>String(t??"").replace(/[&<>"']/g,t=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[t])),num=t=>Number(t||0).toLocaleString("en-US"),t=[["requested","مطلوب"],["referral","تحويل منظار"],["inprogress","قيد التنفيذ"],["done","مكتمل / سليم"],["flag","يستدعي متابعة"],["refused","رفض"],["unfit","غير لائق"],["other","غير مصنف"]];window.__opmSurveyTrend=(t,e,a)=>{const r=[...t].sort((t,e)=>t.date.localeCompare(e.date)),o=Math.max(1,...r.map(t=>t.count)),s=r.reduce((t,e)=>t+e.count,0);return`<section class="opm-chart opm-survey-trend" aria-label="تنفيذ الاستبيانات حسب اليوم"><header><div><b>حركة تنفيذ الاستبيانات</b><small>آخر ${num(r.length)} أيام تنفيذ حتى التاريخ المحدد</small></div><strong>${num(s)}<small>استبيان</small></strong></header>${r.length?`<div class="opm-trend-scroll" tabindex="0" role="group" aria-label="اختر يومًا لعرض الأسماء"><div class="opm-trend-plot" style="--chart-columns:${r.length}">${r.map(t=>`<button type="button" data-survey-day="${esc(t.date)}" aria-pressed="${a==="day"&&t.date===e}" aria-label="${esc(t.date)}: ${num(t.count)} استبيان" title="${esc(t.date)} · ${num(t.count)} استبيان"><b>${num(t.count)}</b><span class="opm-trend-column" aria-hidden="true"><i style="height:${t.count/o*100}%"></i></span><span><strong dir="ltr">${t.date.slice(8)}/${t.date.slice(5,7)}</strong><small>${new Date(t.date+"T12:00:00Z").toLocaleDateString("ar-EG",{weekday:"short",timeZone:"Africa/Cairo"})}</small></span></button>`).join("")}</div></div><div class="opm-chart-caption">اضغط على عمود لعرض أسماء اليوم · المقياس يبدأ من صفر</div>`:'<p class="opm-chart-empty">لا يوجد تنفيذ حتى التاريخ المحدد.</p>'}</section>`}})();